CREATE TYPE "user_role" AS ENUM (
  'user',
  'admin'
);

CREATE TYPE "game_type" AS ENUM (
  'main',
  'dlc',
  'expansion',
  'spinoff',
  'remake',
  'remaster',
  'port',
  'bundle'
);

CREATE TYPE "play_status" AS ENUM (
  'ignore',
  'backlog',
  'playing',
  'completed',
  'dropped'
);

CREATE TYPE "play_priority" AS ENUM (
  'low',
  'medium',
  'high'
);

CREATE TABLE "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar(50) UNIQUE NOT NULL,
  "email" varchar(254) UNIQUE NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "role" user_role NOT NULL DEFAULT 'user',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "publishers" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(150) UNIQUE NOT NULL,
  "website" varchar(255),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "games" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" varchar(255) NOT NULL,
  "original_title" varchar(255),
  "release_date" date,
  "description" text,
  "game_type" game_type NOT NULL DEFAULT 'main',
  "parent_game_id" bigint,
  "website_url" varchar(500),
  "cover_image_url" varchar(500),
  "age_rating" varchar(20),
  "metacritic_score" decimal(4,1),
  "publisher_id" bigint,
  "external_source" varchar(30),
  "external_id" varchar(100),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "ck_games_metacritic" CHECK (metacritic_score is null or metacritic_score between 0 and 100),
  CONSTRAINT "ck_games_not_own_parent" CHECK (parent_game_id is null or parent_game_id <> id),
  CONSTRAINT "ck_games_external_pair" CHECK ((external_source is null) = (external_id is null))
);

CREATE TABLE "platforms" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(150) UNIQUE NOT NULL,
  "short_name" varchar(30),
  "release_date" date,
  "description" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "game_platforms" (
  "game_id" bigint NOT NULL,
  "platform_id" bigint NOT NULL,
  "release_date" date,
  PRIMARY KEY ("game_id", "platform_id")
);

CREATE TABLE "genres" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(80) UNIQUE NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "game_genres" (
  "game_id" bigint NOT NULL,
  "genre_id" bigint NOT NULL,
  PRIMARY KEY ("game_id", "genre_id")
);

CREATE TABLE "franchises" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(150) UNIQUE NOT NULL,
  "description" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "game_franchises" (
  "game_id" bigint NOT NULL,
  "franchise_id" bigint NOT NULL,
  PRIMARY KEY ("game_id", "franchise_id")
);

CREATE TABLE "user_games" (
  "user_id" bigint NOT NULL,
  "game_id" bigint NOT NULL,
  "platform_id" bigint,
  "status" play_status NOT NULL DEFAULT 'backlog',
  "play_priority" play_priority NOT NULL DEFAULT 'medium',
  "is_owned" boolean NOT NULL DEFAULT false,
  "wanna_buy" boolean NOT NULL DEFAULT false,
  "is_favorite" boolean NOT NULL DEFAULT false,
  "personal_rating" decimal(3,1),
  "playtime_minutes" integer,
  "started_at" date,
  "finished_at" date,
  "price_paid" decimal(10,2),
  "currency" char(3) DEFAULT 'BRL',
  "purchased_at" date,
  "store" varchar(100),
  "observations" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "ck_user_games_rating" CHECK (personal_rating is null or personal_rating between 0 and 10),
  CONSTRAINT "ck_user_games_playtime" CHECK (playtime_minutes is null or playtime_minutes >= 0),
  CONSTRAINT "ck_user_games_dates" CHECK (finished_at is null or started_at is null or finished_at >= started_at),
  CONSTRAINT "ck_user_games_price" CHECK (price_paid is null or price_paid >= 0),
  CONSTRAINT "ck_user_games_owned_vs_wanna_buy" CHECK (not (is_owned and wanna_buy)),
  PRIMARY KEY ("user_id", "game_id")
);

CREATE TABLE "lists" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "name" varchar(100) NOT NULL,
  "description" text,
  "is_public" boolean NOT NULL DEFAULT false,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "list_games" (
  "list_id" bigint NOT NULL,
  "game_id" bigint NOT NULL,
  "position" integer NOT NULL DEFAULT 0,
  "added_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "ck_list_games_position" CHECK (position >= 0),
  PRIMARY KEY ("list_id", "game_id")
);

CREATE INDEX ON "games" ("title");

CREATE INDEX ON "games" ("publisher_id");

CREATE INDEX ON "games" ("parent_game_id");

CREATE UNIQUE INDEX "uq_games_external" ON "games" ("external_source", "external_id");

CREATE INDEX ON "game_platforms" ("platform_id");

CREATE INDEX ON "game_genres" ("genre_id");

CREATE INDEX ON "game_franchises" ("franchise_id");

CREATE INDEX ON "user_games" ("game_id");

CREATE INDEX ON "user_games" ("user_id", "status");

CREATE INDEX ON "user_games" ("user_id", "wanna_buy");

CREATE INDEX ON "lists" ("user_id");

CREATE UNIQUE INDEX "uq_lists_user_name" ON "lists" ("user_id", "name");

CREATE INDEX ON "list_games" ("list_id", "position");

CREATE INDEX ON "list_games" ("game_id");

COMMENT ON COLUMN "users"."email" IS 'Normalize to lowercase in the app (or use citext)';

COMMENT ON COLUMN "users"."password_hash" IS 'BCrypt/Argon2 hash only, never plaintext';

COMMENT ON COLUMN "users"."role" IS 'admin can edit the shared catalog';

COMMENT ON COLUMN "games"."parent_game_id" IS 'DLC/expansion/remake points to the base game';

COMMENT ON COLUMN "games"."external_source" IS 'e.g. igdb, rawg - used by future imports';

COMMENT ON COLUMN "game_platforms"."release_date" IS 'Release date on this specific platform (optional)';

COMMENT ON COLUMN "user_games"."platform_id" IS 'Platform you own/play this game on (optional)';

COMMENT ON COLUMN "user_games"."store" IS 'Steam, PSN, physical store, etc.';

ALTER TABLE "games" ADD CONSTRAINT "fk_games_publishers" FOREIGN KEY ("publisher_id") REFERENCES "publishers" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "games" ADD CONSTRAINT "fk_games_parent" FOREIGN KEY ("parent_game_id") REFERENCES "games" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "game_platforms" ADD CONSTRAINT "fk_game_platforms_games" FOREIGN KEY ("game_id") REFERENCES "games" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "game_platforms" ADD CONSTRAINT "fk_game_platforms_platforms" FOREIGN KEY ("platform_id") REFERENCES "platforms" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "game_genres" ADD CONSTRAINT "fk_game_genres_games" FOREIGN KEY ("game_id") REFERENCES "games" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "game_genres" ADD CONSTRAINT "fk_game_genres_genres" FOREIGN KEY ("genre_id") REFERENCES "genres" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "game_franchises" ADD CONSTRAINT "fk_game_franchises_games" FOREIGN KEY ("game_id") REFERENCES "games" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "game_franchises" ADD CONSTRAINT "fk_game_franchises_franchises" FOREIGN KEY ("franchise_id") REFERENCES "franchises" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "user_games" ADD CONSTRAINT "fk_user_games_users" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "user_games" ADD CONSTRAINT "fk_user_games_games" FOREIGN KEY ("game_id") REFERENCES "games" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "user_games" ADD CONSTRAINT "fk_user_games_game_platform" FOREIGN KEY ("game_id", "platform_id") REFERENCES "game_platforms" ("game_id", "platform_id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "lists" ADD CONSTRAINT "fk_lists_users" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "list_games" ADD CONSTRAINT "fk_list_games_lists" FOREIGN KEY ("list_id") REFERENCES "lists" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "list_games" ADD CONSTRAINT "fk_list_games_games" FOREIGN KEY ("game_id") REFERENCES "games" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;
